AssistantMessageToolRequest(name='create', tool_call_id='function-call-7e3fab1a-10c6-4989-b750-3398d564fcad', arguments={'file_text': "const { chromium } = require('playwright');
const fs = require('fs');

(async () => {
  try {
    const browser = await chromium.launch();
    const page = await browser.newPage();
    const htmlContent = fs.readFileSync('index.html', 'utf8');
    await page.setContent(htmlContent);

    // Inject axe-core
    const axeSource = fs.readFileSync('node_modules/axe-core/axe.min.js', 'utf8');
    await page.addScriptTag({ content: axeSource });

    const results = await page.evaluate(async () => {
      return await window.axe.run();
    });

    const violations = results.violations.filter(v => !v.tags.includes('best-practice'));
    console.log(JSON.stringify(violations, null, 2));

    await browser.close();
    process.exit(violations.length ? 1 : 0);
  } catch (err) {
    console.error(err);
    process.exit(1);
