       display: block;
       font-size: 0.875rem;
       font-weight: 500;
       margin-bottom: 0.5rem;
     }

     .required-mark {
       color: var(--error-color);
       margin-left: 0.125rem;
     }

     .required-legend {
       font-size: 0.875rem;
       color: var(--text-muted);
       margin-bottom: 1.5rem;
     }

     input {
       width: 100%;
       padding: 0.625rem 0.75rem;
       border: 1px solid var(--border-color);
       border-radius: 0.5rem;
       font-size: 1rem;
       transition: border-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out;
     }

     input:focus {
       outline: none;
       border-color: var(--primary-color);
       box-shadow: 0 0 0 3px var(--focus-ring);
     }

     input[aria-invalid="true"] {
       border-color: var(--error-color);
     }

     input[aria-invalid="true"]:focus {
       box-shadow: 0 0 0 3px rgba(220, 38, 38, 0.2);
     }

     .helper-text {
       font-size: 0.75rem;
       color: var(--text-muted);
       margin-top: 0.375rem;
     }

     .error-message {
       font-size: 0.75rem;
       color: var(--error-color);
       margin-top: 0.375rem;
       display: none;
     }

     button[type="submit"] {
       width: 100%;
       padding: 0.75rem;
       background-color: var(--primary-color);
       color: white;
       border: none;
       border-radius: 0.5rem;
       font-weight: 600;
       cursor: pointer;
       transition: background-color 0.15s ease-in-out;
     }

     button[type="submit"]:hover {
       background-color: var(--primary-hover);
     }

     button[type="submit"]:focus {
       outline: none;
       box-shadow: 0 0 0 3px var(--focus-ring);
     }

     @media (max-width: 640px) {
       .support-card {
         padding: 1.5rem;
       }
     }
   </style>
 </head>
 <body>
   <main>
     <section class="support-card">
       <h1>Contact Support</h1>
       <p class="subtitle">Fill out the form below and we'll get back to you as soon as possible.</p>

       <p class="required-legend">Fields marked with <span class="required-mark" aria-hidden="true">*</span> are required.</p>

       <form id="contact-form" novalidate>
         <div class="form-field">
           <label for="fullName">
             Full Name <span class="required-mark" aria-hidden="true">*</span>
           </label>
           <input 
             type="text" 
             id="fullName" 
             name="fullName" 
             required 
             autocomplete="name"
             aria-required="true"
             aria-describedby="fullName-error"
           >
           <p id="fullName-error" class="error-message" role="alert"></p>
         </div>

         <div class="form-field">
           <label for="email">
             Email Address <span class="required-mark" aria-hidden="true">*</span>
           </label>
           <input 
             type="email" 
             id="email" 
             name="email" 
             required 
             autocomplete="email"
             aria-required="true"
             aria-describedby="email-error"
           >
           <p id="email-error" class="error-message" role="alert"></p>
         </div>

         <div class="form-field">
           <label for="phone">
             Phone Number (Optional)
           </label>
           <input 
             type="tel" 
             id="phone" 
             name="phone" 
             autocomplete="tel"
             aria-describedby="phone-help phone-error"
           >
           <p id="phone-help" class="helper-text">Format: +1 123-456-7890 or 1234567890</p>
           <p id="phone-error" class="error-message" role="alert"></p>
         </div>

         <button type="submit">Send Support Request</button>
       </form>
     </section>
   </main>

   <script>
     const ContactForm = () => {
       const form = document.getElementById('contact-form');
       const fields = {
         fullName: {
           input: document.getElementById('fullName'),
           error: document.getElementById('fullName-error'),
           validate: (val) => val.trim() ? '' : 'Full name is required'
         },
         email: {
           input: document.getElementById('email'),
           error: document.getElementById('email-error'),
           validate: (val) => {
             if (!val.trim()) return 'Email address is required';
             if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val)) return 'Please enter a valid email address';
             return '';
           }
         },
         phone: {
           input: document.getElementById('phone'),
           error: document.getElementById('phone-error'),
           validate: (val) => {
             if (!val.trim()) return '';
             if (!/^\+?[\d\s-]{10,}$/.test(val)) return 'Please enter a valid phone number (at least 10 digits)';
             return '';
           }
         }
       };

       const updateFieldUI = (fieldName, errorMessage) => {
         const field = fields[fieldName];
         if (errorMessage) {
           field.input.setAttribute('aria-invalid', 'true');
           field.error.textContent = 'Error: ' + errorMessage;
           field.error.style.display = 'block';
         } else {
           field.input.removeAttribute('aria-invalid');
           field.error.textContent = '';
           field.error.style.display = 'none';
         }
       };

       const validateField = (fieldName) => {
         const field = fields[fieldName];
         const error = field.validate(field.input.value);
         updateFieldUI(fieldName, error);
         return !error;
       };

       Object.keys(fields).forEach(fieldName => {
         fields[fieldName].input.addEventListener('blur', () => validateField(fieldName));
         fields[fieldName].input.addEventListener('input', () => {
           if (fields[fieldName].input.getAttribute('aria-invalid') === 'true') {
             const error = fields[fieldName].validate(fields[fieldName].input.value);
             if (!error) updateFieldUI(fieldName, '');
           }
         });
       });

       form.addEventListener('submit', (e) => {
         e.preventDefault();
         let firstInvalidField = null;
         let isValid = true;

         Object.keys(fields).forEach(fieldName => {
           const isFieldValid = validateField(fieldName);
           if (!isFieldValid) {
             isValid = false;
             if (!firstInvalidField) firstInvalidField = fields[fieldName].input;
           }
         });

         if (isValid) {
           alert('Form submitted successfully!');
           form.reset();
           Object.keys(fields).forEach(fieldName => updateFieldUI(fieldName, ''));
         } else if (firstInvalidField) {
           firstInvalidField.focus();
         }
       });
     };

     document.addEventListener('DOMContentLoaded', ContactForm);
   </script>
 </body>
 </html>

')
